#include <iostream>

constexpr unsigned long long factorial(unsigned n) {
    return n <= 1 ? 1 : n * factorial(n - 1);
}

int main() {
    static_assert(factorial(5) == 120);  // checked at compile time
    std::cout << factorial(10) << '\n';
}

