higher-order.code:
#include <iostream>
#include <ranges>

int main() {
    namespace views = std::views;
    auto squares = views::iota(1, 11)
                 | views::filter([](int x) { return x % 2 == 0; })
                 | views::transform([](int x) { return x * x; });

    const char* sep = "";
    for (int x : squares) {
        std::cout << sep << x;
        sep = " ";
    }
    std::cout << '\n';
}

