#include <iostream>
#include <stdexcept>
#include <string>

// RAII: a resource's lifetime is tied to an object's scope.
class Resource {
    std::string name;
public:
    explicit Resource(std::string n) : name(std::move(n)) {
        std::cout << "open " << name << '\n';
    }
    ~Resource() { std::cout << "close " << name << '\n'; }
};

void work() {
    Resource log("log.txt");
    Resource db("db");
    throw std::runtime_error("disk full");
}   // db, then log, are closed while the exception unwinds the stack

int main() {
    try {
        work();
    } catch (const std::exception& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
}
